    case "ArrowLeft": {
      event.preventDefault();

      if (group.orientation === "horizontal") {
        adjustLayoutForSeparator(separatorElement, -5);
      }
      break;
    }
    case "ArrowRight": {
      event.preventDefault();

      if (group.orientation === "horizontal") {
        adjustLayoutForSeparator(separatorElement, 5);
      }
      break;
    }
    case "ArrowUp": {
      event.preventDefault();

      if (group.orientation === "vertical") {
        adjustLayoutForSeparator(separatorElement, -5);
      }
      break;
